        if k == 0:
            return True
        for i in range(h):
            for j in range(w):
                new_matrix = place_piece(piece, i, j)
                if new_matrix and dfs(i, j, k - 1):
                    return True
        return False

    return dfs(0, 0, k)

def solve():
    h, w = map(int, input().split())
    matrix = [input().strip() for _ in range(h)]

    if not is_connected(matrix, h, w):
        print("No solution")
        return

    for k in range(2, 6):
        if is_power(matrix, h, w, k):
            result = [['.' for _ in range(w)] for _ in range(h)]
            piece = find_piece(matrix, h, w)
            if piece:
                x, y = piece
                for i in range(h):
                    for j in range(w):
                        if matrix[i][j] == 'X':
                            result[i][j] = str((i - x) * w + j - y + 1)
            for row in result:
                print(''.join(row))
            return

    print("No solution")

solve()

import sys
from collections import deque

def find_polyomino_powers():
    input = sys.stdin.read
    data = input().strip().split('\n')

    h, w = map(int, data[0].split())
    matrix = [list(data[i + 1]) for i in range(h)]

    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w and matrix[x][y] == 'X'

    def bfs(start_x, start_y):
        queue = deque([(start_x, start_y)])
        shape = []
        matrix[start_x][start_y] = '.'
        while queue:
            x, y = queue.popleft()
            shape.append((x, y))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    matrix[nx][ny] = '.'
                    queue.append((nx, ny))
        return shape

    def normalize_shape(shape):
        min_x = min(x for x, y in shape)
        min_y = min(y for x, y in shape)
        return sorted((x - min_x, y - min_y) for x, y in shape)

    def can_form_k_power(shape, k):
        n = len(shape)
        if n * k > h * w:
            return False
        for i in range(h):
            for j in range(w):
                if matrix[i][j] == '.':
                    continue
                temp_matrix = [row[:] for row in matrix]
                if can_place_shape(temp_matrix, shape, i, j, k):
                    return True
        return False

    def can_place_shape(temp_matrix, shape, start_x, start_y, k):
        for _ in range(k):
            for x, y in shape:
                nx, ny = start_x + x, start_y + y
                if not is_valid(nx, ny):
                    return False
                temp_matrix[nx][ny] = '.'
        return True

    shapes = []
    for i in range(h):
        for j in range(w):
            if matrix[i][j] == 'X':
                shape = bfs(i, j)
                shapes.append(normalize_shape(shape))

    if not shapes:
        print("No solution")
        return

    for k in range(2, 6):
        if all(can_form_k_power(shape, k) for shape in shapes):
            result_matrix = [['.' for _ in range(w)] for _ in range(h)]
            for shape in shapes:
                for i in range(h):
                    for j in range(w):
                        if matrix[i][j] == '.':
                            continue
                        if can_place_shape(result_matrix, shape, i, j, k):
                            for x, y in shape:
                                result_matrix[i + x][j + y] = str(k)
            for row in result_matrix:
                print(''.join(row))
            return

    print("No solution")

find_polyomino_powers()
